Item.method_code:
if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefDelegateDocument|" + aml);
}
var selected = this.node;
var name = selected.SelectSingleNode("name");
var text = name.FirstChild;
var output = new System.Xml.XmlDocument();
eventData.BaseGetItem(output);
if (selected.ParentNode != null || name.InnerText != "Captured value"
    || !Object.ReferenceEquals(text, name.FirstChild))
{
    throw new Exception("The base call discarded its detached captured input");
}
if (this.dom.DocumentElement.Name != "AML"
    || this.dom.SelectSingleNode("AML/comment()").Value != "Native document marker"
    || this.dom.SelectSingleNode("AML/Item/name").InnerText != "Current document value")
{
    throw new Exception("The base call discarded the current document XML");
}
var result = this.getInnovator().newItem();
result.loadAML(output.OuterXml);
return result;

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefReloadBaseDocument|" + aml);
}
var selected = this.node;
this.loadAML("<AML><!--Native document marker--><Item type='RefBaseDocument' action='get'><name>Reloaded document</name></Item></AML>");
selected.SelectSingleNode("name").InnerText = "Captured value";
return this;

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefInspectBaseDocument|" + aml);
}
if (this.dom.DocumentElement.Name != "AML"
    || this.dom.SelectSingleNode("AML/comment()").Value != "Native document marker")
{
    throw new Exception("The later hook lost the native document container");
}
this.setProperty("name", "Current document value");
return this;
